// ==UserScript==
// @name         Instagram rosa pastel
// @match        https://www.instagram.com/*
// @run-at       document-start
// ==/UserScript==

(function () {
  // colorinches
  const C = {
    bg: "#fff6f9",        // fondo general
    card: "#ffffff",      // tarjetas
    soft: "#ffe9f0",      // zonas suaves / inputs
    softer: "#ffd9e6",    // hover / elevado
    border: "#f6cfdc",    // bordes
    text: "#4a2c3a",      // texto principal
    text2: "#a07489",     // texto secundario
    accent: "#ec7fa9",    // acento rosa
    accentDark: "#d6578a" // enlaces y botones
  };

  // Imagen personal incrustada para no depender de archivos o dominios externos.
  const FOTO = "data:image/jpeg;base64,";

  // Marca Explorar antes del primer render para evitar el destello de publicaciones.
  const esExplorarInicial =
    location.pathname === "/explore" || location.pathname === "/explore/";
  if (esExplorarInicial) {
    document.documentElement.setAttribute("data-ig-explore-clean", "1");
  }

  const css = `
    :root, :root.__fb-dark-mode, :root.__fb-light-mode {
      color-scheme: light;
      --ig-primary-background: ${C.bg} !important;
      --ig-secondary-background: ${C.soft} !important;
      --ig-elevated-background: ${C.card} !important;
      --ig-highlight-background: ${C.softer} !important;
      --ig-primary-text: ${C.text} !important;
      --ig-secondary-text: ${C.text2} !important;
      --ig-tertiary-text: ${C.text2} !important;
      --ig-primary-icon: ${C.text} !important;
      --ig-secondary-icon: ${C.text2} !important;
      --ig-link: ${C.accentDark} !important;
      --ig-primary-button: ${C.accentDark} !important;
      --ig-primary-button-hover: ${C.accent} !important;
      --ig-secondary-button: ${C.soft} !important;
      --ig-separator: ${C.border} !important;
      --ig-stroke: ${C.border} !important;
      --ig-badge: ${C.accentDark} !important;
    }

    html, body {
      background-color: ${C.bg} !important;
      color: ${C.text} !important;
      font-family: -apple-system, "SF Pro Rounded", system-ui, sans-serif !important;
      -webkit-font-smoothing: antialiased;
    }

    ::selection { background: ${C.accent}; color: #fff; }
    input, textarea { caret-color: ${C.accentDark}; accent-color: ${C.accentDark}; }

    /* Enlaces: nunca azules */
    a, a:visited { color: ${C.accentDark}; }

    /* Publicaciones como tarjetas */
    article {
      background: ${C.card} !important;
      border: 1px solid ${C.border} !important;
      border-radius: 20px !important;
      overflow: hidden;
      margin: 12px 8px !important;
      box-shadow: 0 6px 18px rgba(236, 127, 169, 0.15);
    }

    /* Campos de texto */
    input[type="text"], input[type="search"], input[type="password"], textarea {
      border-radius: 16px !important;
      background-color: ${C.soft} !important;
      color: ${C.text} !important;
    }

    /* Barra de navegación (superior e inferior): SÓLIDA */
    nav, [data-ig-bottombar] {
      background-color: ${C.card} !important;
      -webkit-backdrop-filter: none !important;
      backdrop-filter: none !important;
      opacity: 1 !important;
      border-color: ${C.border} !important;
      box-shadow: 0 -2px 14px rgba(236, 127, 169, 0.18);
    }

    /* Barra superior: mantener el fondo visible al desplazarse */
    nav:not([data-ig-bottombar]), [role="banner"] {
      position: sticky !important;
      top: 0 !important;
      z-index: 100 !important;
      background-color: ${C.card} !important;
      background-attachment: fixed !important;
      -webkit-backdrop-filter: none !important;
      backdrop-filter: none !important;
    }

    /* Iconos legibles */
    svg { color: ${C.text}; }
    nav svg, [data-ig-bottombar] svg { color: ${C.text} !important; }
    nav svg[fill]:not([fill="none"]), [data-ig-bottombar] svg[fill]:not([fill="none"]) { fill: currentColor; }

    /* Ventanas emergentes */
    [role="dialog"] {
      border-radius: 22px !important;
      background-color: ${C.card} !important;
      color: ${C.text} !important;
    }

    button[type="submit"] { border-radius: 14px !important; }

    /* Área de Explorar limpia, sin afectar la barra ni sus resultados */
    html[data-ig-explore-clean], html[data-ig-explore-clean] body {
      background-color: ${C.bg} !important;
      overflow: hidden !important;
    }

    [data-ig-explore-clean] #mi-foto-explorar {
      display: block;
      position: fixed;
      top: 50%;
      left: 50%;
      z-index: 2;
      width: min(280px, calc(100vw - 32px));
      height: auto;
      margin: 0;
      transform: translate(-50%, -50%);
      border: 2px solid ${C.border};
      border-radius: 18px;
      box-shadow: 0 6px 18px rgba(236, 127, 169, 0.2);
      object-fit: cover;
    }

    /* Oculta publicaciones y reels desde el primer estilo, antes del observer. */
    [data-ig-explore-clean]:not(:has(input:focus)) a[href*="/p/"],
    [data-ig-explore-clean]:not(:has(input:focus)) a[href*="/reel/"] {
      display: none !important;
    }
  `;
  const style = document.createElement("style");
  style.textContent = css;
  (document.head || document.documentElement).appendChild(style);

  const vistos = new WeakSet();

  function esAzul(rgb) {
    const m = rgb && rgb.match(/\d+(\.\d+)?/g);
    if (!m) return false;
    const [r, g, b] = m.map(Number);
    return b > 180 && r < 120 && b - r > 80 && g < b;
  }


  function recolorearAzules() {
    document
      .querySelectorAll("a, span, button, [role='button'], svg, path, div[dir]")
      .forEach(el => {
        if (vistos.has(el)) return;
        vistos.add(el);
        const cs = getComputedStyle(el);
        if (esAzul(cs.color)) el.style.setProperty("color", C.accentDark, "important");
        if (esAzul(cs.fill)) el.style.setProperty("fill", C.accentDark, "important");
        if (esAzul(cs.backgroundColor)) el.style.setProperty("background-color", C.accentDark, "important");
        if (esAzul(cs.borderTopColor)) el.style.setProperty("border-color", C.accentDark, "important");
      });
  }

  // barra inferior
  function solidificarBarraInferior() {
    document.querySelectorAll('a[href="/"], a[href^="/direct"]').forEach(a => {
      let n = a;
      for (let i = 0; i < 10 && n.parentElement; i++) {
        n = n.parentElement;
        const cs = getComputedStyle(n);
        if (cs.position === "fixed" && parseInt(cs.bottom) === 0) {
          n.setAttribute("data-ig-bottombar", "1");
          return;
        }
      }
    });
  }

  // notifs
  function arreglarGlobitos() {
    const enlaces = document.querySelectorAll(
      'nav a, [data-ig-bottombar] a, a[href^="/direct"], a[href*="notifications"], a[href*="activity"]'
    );
    enlaces.forEach(a => {
      a.querySelectorAll("div, span").forEach(el => {
        if (el.dataset.igBadge) return;
        // Ignora iconos, avatares e imágenes
        if (el.querySelector("svg, img, canvas") || el.closest("svg")) return;

        const r = el.getBoundingClientRect();
        if (r.width < 6 || r.height < 6 || r.width > 28 || r.height > 28) return;

        const cs = getComputedStyle(el);
        const radio = parseFloat(cs.borderTopLeftRadius) || 0;
        const redondo =
          radio >= Math.min(r.width, r.height) / 2 - 1 ||
          cs.borderTopLeftRadius.includes("%");
        if (!redondo) return;

        el.dataset.igBadge = "1";
        el.style.setProperty("background-color", C.accentDark, "important");
        el.style.setProperty("border", "2px solid #ffffff", "important");
        el.style.setProperty("color", "#ffffff", "important");
        el.style.setProperty("box-sizing", "border-box", "important");
        el.style.setProperty("font-size", "11px", "important");
        el.style.setProperty("font-weight", "700", "important");
        el.style.setProperty("display", "flex", "important");
        el.style.setProperty("align-items", "center", "important");
        el.style.setProperty("justify-content", "center", "important");
        el.style.setProperty("box-shadow", "0 1px 4px rgba(214, 87, 138, 0.45)", "important");
      });
    });
  }

  // sacar cartel molesto
  const TEXTOS_APP = [
    "open app", "open in app", "open instagram", "use the app", "get the app",
    "abrir app", "abrir en la app Instagram", "abrir en la app", "abrir instagram",
    "usar la app", "usar la aplicación", "obtener la app", "descargar la app"
  ];

  function quitarBannerApp() {
    document.querySelectorAll('a, button, [role="button"]').forEach(el => {
      const texto = el.textContent.trim().toLowerCase();
      const esTienda = /apps\.apple\.com|itunes\.apple\.com/.test(el.getAttribute("href") || "");
      if (!esTienda && !TEXTOS_APP.includes(texto)) return;

      let n = el;
      for (let i = 0; i < 8 && n.parentElement; i++) {
        n = n.parentElement;
        const pos = getComputedStyle(n).position;
        if (pos === "fixed" || pos === "sticky") {
          n.style.display = "none";
          return;
        }
      }
      const dialogo = el.closest('[role="dialog"]');
      if (dialogo) {
        dialogo.style.display = "none";
        document.body.style.overflow = "auto";
      }
    });
  }

  // ocultado de reels y anuncios
  const PATROCINADO = ["Sponsored", "Publicidad", "Patrocinado"];

  function limpiarFeed() {
    if (location.pathname.startsWith("/reels")) {
      location.replace("/");
      return;
    }
    document.querySelectorAll('a[href^="/reels"]').forEach(a => {
      a.style.display = "none";
    });
    document.querySelectorAll("article").forEach(post => {
      const esAnuncio = [...post.querySelectorAll("span")]
        .some(s => PATROCINADO.includes(s.textContent.trim()));
      const esReel = post.querySelector('a[href*="/reel/"]');
      if (esAnuncio || esReel) post.style.display = "none";
    });
  }

  // Comprueba que la ruta sea exactamente Explorar, sin incluir sus búsquedas.
  function esExplorarPrincipal() {
    return location.pathname === "/explore" || location.pathname === "/explore/";
  }

  // Devuelve true mientras la persona está usando la barra de búsqueda.
  function busquedaExplorarActiva() {
    const elemento = document.activeElement;
    return elemento instanceof HTMLInputElement &&
      (elemento.type === "search" ||
        elemento.matches('[placeholder*="Search" i], [placeholder*="Buscar" i], [aria-label*="Search" i], [aria-label*="Buscar" i]'));
  }

  // Restaura únicamente los elementos que este bloque ocultó en Explorar.
  function mostrarResultadosExplorar() {
    document.querySelectorAll("[data-ig-explore-hidden]").forEach(el => {
      el.style.removeProperty("display");
      el.removeAttribute("data-ig-explore-hidden");
    });
  }

  // Oculta publicaciones y limpia las filas vacías sin eliminar nodos de React.
  function limpiarExplorar() {
    if (!esExplorarPrincipal()) {
      mostrarResultadosExplorar();
      document.documentElement.removeAttribute("data-ig-explore-clean");
      document.getElementById("mi-foto-explorar")?.remove();
      return;
    }

    document.documentElement.setAttribute("data-ig-explore-clean", "1");

    if (busquedaExplorarActiva()) {
      mostrarResultadosExplorar();
      return;
    }

    document.querySelectorAll('a[href*="/p/"], a[href*="/reel/"]').forEach(a => {
      a.style.setProperty("display", "none", "important");
      a.setAttribute("data-ig-explore-hidden", "1");
    });

    document.querySelectorAll('a[href*="/p/"], a[href*="/reel/"]').forEach(a => {
      let contenedor = a.parentElement;
      for (let i = 0; i < 5 && contenedor; i++, contenedor = contenedor.parentElement) {
        const enlacesPublicacion = contenedor.querySelectorAll('a[href*="/p/"], a[href*="/reel/"]');
        if (enlacesPublicacion.length && [...enlacesPublicacion].every(enlace =>
          getComputedStyle(enlace).display === "none"
        )) {
          contenedor.style.setProperty("display", "none", "important");
          contenedor.setAttribute("data-ig-explore-hidden", "1");
          break;
        }
      }
    });

    // Inserta la imagen debajo de la barra de búsqueda una sola vez.
    if (!document.getElementById("mi-foto-explorar")) {
      const busqueda = document.querySelector(
        'input[type="search"], input[placeholder*="Search" i], input[placeholder*="Buscar" i], input[aria-label*="Search" i], input[aria-label*="Buscar" i]'
      );
      if (busqueda) {
        const barra = busqueda.closest('[role="search"]') || busqueda.parentElement;
        if (barra?.parentElement) {
          const foto = document.createElement("img");
          foto.id = "mi-foto-explorar";
          foto.src = FOTO;
          foto.alt = "Mi foto";
          barra.insertAdjacentElement("afterend", foto);
        }
      }
    }
  }

  function ejecutar() {
    quitarBannerApp();
    solidificarBarraInferior();
    arreglarGlobitos();
    recolorearAzules();
    limpiarExplorar();
    if (location.pathname.startsWith("/direct")) return; // no tocar el contenido de mensajes
    limpiarFeed();
  }

  function iniciar() {
    ejecutar();
    // Permite que los resultados vuelvan a verse al enfocar o escribir.
    document.addEventListener("focusin", limpiarExplorar);
    document.addEventListener("input", limpiarExplorar);
    let t;
    new MutationObserver(() => {
      clearTimeout(t);
      t = setTimeout(ejecutar, 400);
    }).observe(document.body, { childList: true, subtree: true });
  }

  if (document.body) iniciar();
  else document.addEventListener("DOMContentLoaded", iniciar);
})();
